/*
 * @module   sigma_rom
 * @brief    SwiGLU sigmoid lookup: sigma(x/16) in Q.6 for every int8 gate code x (Vectorized, combinational).
 * @details  GENERATED by tools/scripts/llama32_1b/gen_rom_sv.py from tools/models/vpu_ops.py (_sigma_table_sym); do not edit by hand.
 *           silu(x) = x * sigma(x) needs sigma only at the 256 int8 gate codes. sigma(-x) = 1 - sigma(x), and neighbouring codes share an
 *           entry: the table holds sigma((2b + 1/2) / 16) for b = |x| >> 1 (b = 63 also covers |x| = 128), rounded to 6 fractional bits
 *           (64 entries of 7 bits: values reach 64 = 1.0). Negative codes read 64 - entry. Accuracy against the earlier 256-entry
 *           table of the alpha - exp - ln chain: same perplexity within noise (docs/llama/accuracy-study.md).
 *           Bit-exact to tr_math_model.hpp::sw2_silu and vpu_ops.sigma_for (verified by the swiglu regression).
 *
 * @param    N   Vector dimension.
 */
module sigma_rom #(
    parameter int N = 8
)(
    input  logic signed [7:0] x     [N],
    output logic        [6:0] sigma [N]
);

    function automatic logic [6:0] lookup(input logic [5:0] b);
        case (b)
            6'd0: lookup = 7'd32;
            6'd1: lookup = 7'd34;
            6'd2: lookup = 7'd36;
            6'd3: lookup = 7'd38;
            6'd4: lookup = 7'd40;
            6'd5: lookup = 7'd42;
            6'd6: lookup = 7'd44;
            6'd7: lookup = 7'd46;
            6'd8: lookup = 7'd47;
            6'd9: lookup = 7'd49;
            6'd10: lookup = 7'd50;
            6'd11: lookup = 7'd51;
            6'd12: lookup = 7'd53;
            6'd13: lookup = 7'd54;
            6'd14: lookup = 7'd55;
            6'd15: lookup = 7'd56;
            6'd16: lookup = 7'd57;
            6'd17: lookup = 7'd57;
            6'd18: lookup = 7'd58;
            6'd19: lookup = 7'd59;
            6'd20: lookup = 7'd59;
            6'd21: lookup = 7'd60;
            6'd22: lookup = 7'd60;
            6'd23: lookup = 7'd61;
            6'd24: lookup = 7'd61;
            6'd25: lookup = 7'd61;
            6'd26: lookup = 7'd62;
            6'd27: lookup = 7'd62;
            6'd28: lookup = 7'd62;
            6'd29: lookup = 7'd62;
            6'd30: lookup = 7'd63;
            6'd31: lookup = 7'd63;
            6'd32: lookup = 7'd63;
            6'd33: lookup = 7'd63;
            6'd34: lookup = 7'd63;
            6'd35: lookup = 7'd63;
            6'd36: lookup = 7'd63;
            6'd37: lookup = 7'd63;
            6'd38: lookup = 7'd63;
            6'd39: lookup = 7'd64;
            6'd40: lookup = 7'd64;
            6'd41: lookup = 7'd64;
            6'd42: lookup = 7'd64;
            6'd43: lookup = 7'd64;
            6'd44: lookup = 7'd64;
            6'd45: lookup = 7'd64;
            6'd46: lookup = 7'd64;
            6'd47: lookup = 7'd64;
            6'd48: lookup = 7'd64;
            6'd49: lookup = 7'd64;
            6'd50: lookup = 7'd64;
            6'd51: lookup = 7'd64;
            6'd52: lookup = 7'd64;
            6'd53: lookup = 7'd64;
            6'd54: lookup = 7'd64;
            6'd55: lookup = 7'd64;
            6'd56: lookup = 7'd64;
            6'd57: lookup = 7'd64;
            6'd58: lookup = 7'd64;
            6'd59: lookup = 7'd64;
            6'd60: lookup = 7'd64;
            6'd61: lookup = 7'd64;
            6'd62: lookup = 7'd64;
            6'd63: lookup = 7'd64;
            default: lookup = 7'd64;
        endcase
    endfunction

    always_comb begin
        for (int i = 0; i < N; i++) begin
            logic [7:0] a;                       // |x| (128 for x = -128)
            logic [5:0] b;
            logic [6:0] e;
            a = x[i][7] ? (~x[i] + 8'd1) : x[i];
            b = a[7] ? 6'd63 : a[6:1];
            e = lookup(b);
            sigma[i] = x[i][7] ? (7'd64 - e) : e;
        end
    end

endmodule
